<?php $title='Edit tenant'; ?><section class="page-header"><div><span class="eyebrow">Platform</span><h1>Edit <?=e($tenant['name']??'tenant')?></h1><p>Manage organization details and access domains.</p></div><a class="btn btn-secondary" href="<?=e(url('platform/tenant-view?id='.(int)($tenant['id']??0)))?>">View tenant</a></section><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif?>
<section class="content-card"><form method="post" class="form-stack"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="update"><div class="form-grid"><div class="field"><label>Name</label><input name="name" required value="<?=e($tenant['name']??'')?>"></div><div class="field"><label>Slug</label><input name="slug" required pattern="[a-z0-9-]+" value="<?=e($tenant['slug']??'')?>"></div></div><button class="btn btn-primary">Save details</button></form></section>
<section class="content-card"><h2>Add custom domain</h2><p class="muted">Example: gatepass.gleehotel.co.ke. New domains remain pending until DNS verification is implemented.</p><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="add_domain"><div class="field"><label>Domain</label><input name="domain" required placeholder="gatepass.example.com"></div><div class="field"><label>&nbsp;</label><button class="btn btn-secondary">Add domain</button></div></form></section>
<section class="content-card"><h2>Domains</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Domain</th><th>Type</th><th>Primary</th><th>Verified</th><th>Action</th></tr></thead><tbody><?php foreach(($tenant['domains']??[]) as $d):?><tr><td><?=e($d['domain'])?></td><td><?=e($d['type'])?></td><td><?=!empty($d['is_primary'])?'Yes':'No'?></td><td><?=!empty($d['is_verified'])?'Yes':'Pending'?></td><td><div class="inline-actions"><?php if(empty($d['is_primary'])):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="primary"><input type="hidden" name="domain_id" value="<?= (int)$d['id']?>"><button class="btn btn-secondary">Make primary</button></form><?php endif?><?php if(($d['type']??'')==='custom'):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="delete_domain"><input type="hidden" name="domain_id" value="<?= (int)$d['id']?>"><button class="btn btn-danger" data-confirm="Remove this domain?">Remove</button></form><?php endif?></div></td></tr><?php endforeach?></tbody></table></div></section>